function gameHasBot(s){return !s?false:['gomoku','xiangqi','chess','go'].includes(s.kind)?(s.players||[]).some(x=>String(x||'').startsWith('BOT:')):(s.seats||[]).some(x=>x&&(x.isBot||String(x.userId||'').startsWith('BOT:')))}
function botControlsForSeat(s,i,occupied){if(occupied&&String(occupied).startsWith('BOT:'))return `<button data-act="remove-bot" data-seat="${i}">移除 AI</button>`;const hasHuman=(s.players||[]).some(x=>x&&!String(x).startsWith('BOT:'));if(!occupied&&hasHuman)return `<button data-act="add-bot" data-seat="${i}">+ AI</button>`;return ''}
function twoPlayerHeader(s,labels){const me=s.players.indexOf(state.profile.userId),practice=gameHasBot(s);return `<div class="players-bar">${s.players.map((u,i)=>`<span class="player-chip ${s.turn===i&&s.started?'turn':''} ${String(u||'').startsWith('BOT:')?'bot-chip':''}">${labels[i]}：${u?esc(userName(u)):'空位'} ${u?`<em class="ready-mark ${s.ready?.[i]?'ready':''}">${s.ready?.[i]?'READY':'未准备'}</em>`:''} ${botControlsForSeat(s,i,u)}</span>`).join('')}</div>${practice?'<span class="practice-badge">AI 对局 · 真人胜负计入对应游戏排行榜 / AI 本身不入榜</span>':''}<div class="game-toolbar">${me<0&&s.players.some(x=>!x)?'<button data-act="join" class="primary">加入对局</button>':''}${me>=0?`<button data-act="ready" class="${s.ready?.[me]?'':'primary'}">${s.ready?.[me]?'取消准备':'准备'}</button><button data-act="leave">离开座位</button>${s.winner||s.result?'<button data-act="reset">新一局</button>':''}`:''}</div><div class="ready-help">${s.started?'对局已开始':'真人全部准备后自动开始；AI 永远视为已准备'}</div>`}
function bindBasic(e){e.querySelectorAll('[data-act="join-seat"]').forEach(b=>b.addEventListener('click',()=>gameAction({type:'join',seat:+b.dataset.seat})));e.querySelector('[data-act="join"]')?.addEventListener('click',()=>gameAction({type:'join'}));e.querySelector('[data-act="ready"]')?.addEventListener('click',()=>gameAction({type:'ready'}));e.querySelector('[data-act="leave"]')?.addEventListener('click',()=>gameAction({type:'leave'}));e.querySelector('[data-act="reset"]')?.addEventListener('click',()=>gameAction({type:'reset'}));e.querySelectorAll('[data-act="add-bot"]').forEach(b=>b.onclick=()=>gameAction({type:'add_bot',seat:+b.dataset.seat}));e.querySelectorAll('[data-act="remove-bot"]').forEach(b=>b.onclick=()=>gameAction({type:'remove_bot',seat:+b.dataset.seat}));e.querySelector('[data-act="set-time"]')?.addEventListener('click',()=>gameAction({type:'set_time_control',freeMs:+e.querySelector('[data-free-sec]').value*1000,bankMs:+e.querySelector('[data-bank-sec]').value*1000}))}
function readyReminderHtml(s){
  if(!s||!state.profile)return'';let p=null,ready=false,active=false,count=0;
  if(Array.isArray(s.players)){const i=s.players.indexOf(state.profile.userId);if(i<0)return'';p=s.players[i];ready=!!s.ready?.[i];active=!!s.started;count=s.players.filter(Boolean).length}
  else{p=(s.seats||[]).find(x=>x?.userId===state.profile.userId);if(!p)return'';ready=!!p.ready;active=['playing','dealer','preflop','flop','turn','river','run_choice','reaction'].includes(s.phase);count=(s.seats||[]).filter(Boolean).length}
  if(!p||ready||active)return'';const sec=Math.min(120,45+Math.max(0,count-1)*10);
  return `<div class="ready-reminder"><div><b>轮到你准备了</b><small>你已经入座。点击准备后才会进入下一局；当前人数下未准备座位约 ${sec} 秒后才会自动释放。</small></div><button type="button" data-ready-reminder class="primary">立即 READY</button></div>`
}
function renderGame(e){if(!state.game){e.innerHTML='<div class="notice">正在加载游戏...</div>';return}({dice:renderDice,gomoku:renderGomoku,xiangqi:renderXiangqi,chess:renderChess,blackjack:renderBlackjack,poker:renderPoker,go:renderGo,uno:renderUno,mahjong:renderMahjong,doudizhu:renderDoudizhu,sudoku:renderSudoku,minesweeper:renderMinesweeper})[state.game.kind]?.(e);const r=readyReminderHtml(state.game);if(r)e.insertAdjacentHTML('afterbegin',r);e.querySelector('[data-ready-reminder]')?.addEventListener('click',()=>gameAction({type:'ready'}))}
function freshAnim(scope,sig){if(!sig)return false;const k=`${state.roomTarget||'room'}:${scope}`;if(state.animationSeen[k]===sig)return false;state.animationSeen[k]=sig;return true}
function seatPos(r,seat){return r.top===seat?'top':r.left===seat?'left':r.right===seat?'right':'bottom'}
function starHtml(x,y){return `<i class="board-star" style="left:${18+x*34-3}px;top:${18+y*34-3}px"></i>`}
function fitFixedBoard(scope,selector,naturalW,naturalH){
  requestAnimationFrame(()=>{
    const board=scope?.querySelector(selector);if(!board)return;const shell=board.parentElement;if(!shell)return;
    let stage=board.parentElement?.classList?.contains('board-scale-stage')?board.parentElement:null;
    if(!stage){stage=document.createElement('div');stage.className='board-scale-stage';shell.insertBefore(stage,board);stage.appendChild(board)}
    board.dataset.fitNaturalW=String(naturalW);board.dataset.fitNaturalH=String(naturalH);
    const maxW=Math.max(220,(shell.clientWidth||innerWidth)-10),scale=Math.min(1,maxW/naturalW);
    shell.style.overflow='hidden';shell.style.touchAction='pan-y';stage.style.width=`${Math.ceil(naturalW*scale)}px`;stage.style.height=`${Math.ceil(naturalH*scale)}px`;
    board.style.setProperty('transform',`scale(${scale})`,'important');board.style.setProperty('transform-origin','top left','important');
    board.style.setProperty('margin','0','important');
  })
}
function refitFixedBoards(){document.querySelectorAll('[data-fit-natural-w]').forEach(board=>{const shell=board.closest('.board-scale-stage')?.parentElement||board.parentElement;if(!shell)return;const w=+board.dataset.fitNaturalW||board.offsetWidth,h=+board.dataset.fitNaturalH||board.offsetHeight;let stage=board.parentElement;if(!stage?.classList?.contains('board-scale-stage'))return;const maxW=Math.max(220,(shell.clientWidth||innerWidth)-10),scale=Math.min(1,maxW/w);shell.style.overflow='hidden';shell.style.touchAction='pan-y';stage.style.width=`${Math.ceil(w*scale)}px`;stage.style.height=`${Math.ceil(h*scale)}px`;board.style.setProperty('transform',`scale(${scale})`,'important')})}
if(!window.__slimeFixedBoardResize){window.__slimeFixedBoardResize=true;window.addEventListener('resize',()=>requestAnimationFrame(refitFixedBoards),{passive:true})}

async function paySingleRound(kind){try{const x=await post('/api/game/entry',creds({kind}));if(x.profile){state.profile={...state.profile,...x.profile};paintSelf()}if(x.fee)toast(`${GAME_NAMES[kind]} · 本局费用 -${x.fee}`);return true}catch(err){toast(err.message);return false}}
async function enterSingleRoom(def){
  const id=def.id;if(state.roomTarget&&state.roomTarget!==id)backgroundForeground();let game=state.singleGames[id];if(!game){if(!await paySingleRound(def.game)){showSection('games');return}game=def.game==='sudoku'?createLocalSudoku(def):createLocalMines(def);state.singleGames[id]=game}const sess={id,room:def,ws:null,users:[state.profile],messages:[],music:null,game,manualClose:false,transport:'single'};state.sessions[id]=sess;state.roomTarget=id;syncForeground(sess);hidePages();$('#roomView').classList.remove('hidden');$('#roomTitle').textContent=def.name;$('#roomMeta').textContent=`${GAME_NAMES[def.game]} · 单机 · 每个新题 / 新局单独计费`;renderRoomShell();setConn('service','单机模式');
}
function localGameRefresh(){const sess=sessionFor(state.roomTarget);if(!sess)return;sess.game=state.game;state.singleGames[sess.id]=state.game;renderMain()}
function sudokuBase(){const base=3,side=9,pattern=(r,c)=>(base*(r%base)+Math.floor(r/base)+c)%side,shuffle=x=>x.map(v=>[Math.random(),v]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]),nums=shuffle([1,2,3,4,5,6,7,8,9]),rows=shuffle([0,1,2]).flatMap(g=>shuffle([0,1,2]).map(r=>g*3+r)),cols=shuffle([0,1,2]).flatMap(g=>shuffle([0,1,2]).map(c=>g*3+c));return rows.map(r=>cols.map(c=>nums[pattern(r,c)]))}
function sudokuSolutionCount(board,limit=2){let best=null,bestOpts=null;for(let y=0;y<9;y++)for(let x=0;x<9;x++)if(!board[y][x]){const used=new Set([...board[y],...board.map(r=>r[x])]);const by=Math.floor(y/3)*3,bx=Math.floor(x/3)*3;for(let yy=by;yy<by+3;yy++)for(let xx=bx;xx<bx+3;xx++)used.add(board[yy][xx]);const opts=[];for(let n=1;n<=9;n++)if(!used.has(n))opts.push(n);if(!opts.length)return 0;if(!bestOpts||opts.length<bestOpts.length){best=[x,y];bestOpts=opts;if(opts.length===1)break}}if(!best)return 1;let count=0;const [x,y]=best;for(const n of bestOpts){board[y][x]=n;count+=sudokuSolutionCount(board,limit-count);board[y][x]=0;if(count>=limit)return count}return count}
function createLocalSudoku(def){const solution=sudokuBase(),target=def.difficulty==='easy'?40:def.difficulty==='medium'?50:56,puzzle=solution.map(r=>r.slice()),cells=[...Array(81).keys()].sort(()=>Math.random()-.5);let holes=0;for(const n of cells){if(holes>=target)break;const y=Math.floor(n/9),x=n%9,old=puzzle[y][x];puzzle[y][x]=0;if(sudokuSolutionCount(puzzle.map(r=>r.slice()),2)===1)holes++;else puzzle[y][x]=old}return {kind:'sudoku',solution,puzzle,board:puzzle.map(r=>r.slice()),fixed:puzzle.map(r=>r.map(Boolean)),wrong:[],complete:false,difficulty:def.difficulty,unique:true,holes}}
function createLocalMines(def){const {w,h,mines}=def.board;return {kind:'minesweeper',w,h,mines,grid:Array.from({length:h},()=>Array.from({length:w},()=>({mine:false,n:0,open:false,flag:false}))),started:false,ended:false,won:false,opened:0,startAt:0}}
function minesPlant(s,sx,sy){const cells=[];for(let y=0;y<s.h;y++)for(let x=0;x<s.w;x++)if(Math.abs(x-sx)>1||Math.abs(y-sy)>1)cells.push([x,y]);cells.sort(()=>Math.random()-.5);for(const [x,y] of cells.slice(0,s.mines))s.grid[y][x].mine=true;for(let y=0;y<s.h;y++)for(let x=0;x<s.w;x++)if(!s.grid[y][x].mine){let n=0;for(let yy=y-1;yy<=y+1;yy++)for(let xx=x-1;xx<=x+1;xx++)if(s.grid[yy]?.[xx]?.mine)n++;s.grid[y][x].n=n}s.started=true;s.startAt=Date.now()}
function minesOpen(s,x,y){const c=s.grid[y]?.[x];if(!c||c.open||c.flag||s.ended)return;if(!s.started)minesPlant(s,x,y);if(c.mine){c.open=true;s.ended=true;s.won=false;for(const r of s.grid)for(const z of r)if(z.mine)z.open=true;return}const q=[[x,y]],seen=new Set;while(q.length){const [cx,cy]=q.shift(),k=`${cx},${cy}`,z=s.grid[cy]?.[cx];if(!z||seen.has(k)||z.open||z.flag||z.mine)continue;seen.add(k);z.open=true;s.opened++;if(z.n===0)for(let yy=cy-1;yy<=cy+1;yy++)for(let xx=cx-1;xx<=cx+1;xx++)if(xx!==cx||yy!==cy)q.push([xx,yy])}if(s.opened>=s.w*s.h-s.mines){s.ended=true;s.won=true}}
function minesChord(s,x,y){const c=s.grid[y]?.[x];if(!c?.open||!c.n||s.ended)return;let flags=0;for(let yy=y-1;yy<=y+1;yy++)for(let xx=x-1;xx<=x+1;xx++)if(s.grid[yy]?.[xx]?.flag)flags++;if(flags!==c.n)return;for(let yy=y-1;yy<=y+1;yy++)for(let xx=x-1;xx<=x+1;xx++)if(xx!==x||yy!==y)minesOpen(s,xx,yy)}

function renderSudoku(e){const s=state.game;e.innerHTML=`<div class="single-game"><div class="game-status">${s.complete?'完成！':'填写 1~9，错误会标红'}</div><div class="sudoku-board">${s.board.flatMap((r,y)=>r.map((v,x)=>`<input inputmode="numeric" maxlength="1" data-sx="${x}" data-sy="${y}" class="${s.fixed[y][x]?'fixed':''} ${s.wrong?.some(k=>k===x+','+y)?'wrong':''}" value="${v||''}" ${s.fixed[y][x]?'disabled':''}>`)).join('')}</div><div class="game-toolbar"><button id="sudokuCheck" class="primary">检查</button><button id="sudokuReset">清空填写</button><button id="sudokuNew">新题</button></div></div>`;e.querySelectorAll('[data-sx]').forEach(i=>i.oninput=()=>{const x=+i.dataset.sx,y=+i.dataset.sy,v=Number(i.value.replace(/[^1-9]/g,''))||0;i.value=v||'';s.board[y][x]=v});$('#sudokuCheck').onclick=()=>{s.wrong=[];for(let y=0;y<9;y++)for(let x=0;x<9;x++)if(s.board[y][x]&&s.board[y][x]!==s.solution[y][x])s.wrong.push(`${x},${y}`);s.complete=s.wrong.length===0&&s.board.flat().every(Boolean);localGameRefresh();toast(s.complete?'数独完成':'还有空格或错误')};$('#sudokuReset').onclick=()=>{s.board=s.puzzle.map(r=>r.slice());s.wrong=[];s.complete=false;localGameRefresh()};$('#sudokuNew').onclick=async()=>{const def=state.room;if(!await paySingleRound(def.game))return;state.game=createLocalSudoku(def);localGameRefresh()}}
function renderMinesweeper(e){const s=state.game,flags=s.grid.flat().filter(x=>x.flag).length;e.innerHTML=`<div class="single-game"><div class="game-status">${s.ended?(s.won?'扫雷成功':'踩雷了'):`剩余雷：${Math.max(0,s.mines-flags)} · 左键翻开 / 右键标旗 / 点击已开数字可快速展开`}</div><div class="mine-board" style="--mw:${s.w}">${s.grid.flatMap((r,y)=>r.map((c,x)=>`<button data-mx="${x}" data-my="${y}" class="mine-cell ${c.open?'open':''} ${c.mine&&c.open?'boom':''}">${c.flag?'⚑':c.open?(c.mine?'✹':c.n||''):''}</button>`)).join('')}</div><div class="game-toolbar"><button id="mineNew" class="primary">重新开始</button></div></div>`;e.querySelectorAll('.mine-cell').forEach(b=>{b.onclick=()=>{const x=+b.dataset.mx,y=+b.dataset.my,c=s.grid[y]?.[x];if(c?.open)minesChord(s,x,y);else minesOpen(s,x,y);localGameRefresh()};b.oncontextmenu=ev=>{ev.preventDefault();const c=s.grid[+b.dataset.my][+b.dataset.mx];if(!c.open&&!s.ended)c.flag=!c.flag;localGameRefresh()}});$('#mineNew').onclick=async()=>{if(!await paySingleRound(state.room.game))return;state.game=createLocalMines(state.room);localGameRefresh()}}
function humanSeatCount(s){return (s.seats||[]).filter(p=>p&&!p.isBot&&!String(p.userId||'').startsWith('BOT:')).length}
function extraSeatControls(s,min=2){const me=(s.seats||[]).findIndex(x=>x?.userId===state.profile.userId),occ=(s.seats||[]).filter(Boolean),humans=humanSeatCount(s),canStart=me>=0&&!!s.seats[me]?.ready&&occ.length>=min&&occ.every(p=>p.isBot||String(p.userId||'').startsWith('BOT:')||p.ready);return `<div class="seat-grid compact">${(s.seats||[]).map((p,i)=>`<div class="seat ${s.turnSeat===i?'turn':''}"><b>${i+1}号位 · ${esc(seatName(p))}</b>${p?`<small>${p.isBot?'AI · READY':p.ready?'READY':'未准备'}${p.result?` · ${esc(p.result)}`:''}${p.handCount!=null?` · ${p.handCount}张`:''}</small>${p.isBot?`<button data-remove-bot="${i}">移除 AI</button>`:''}`:`<button data-seat="${i}">坐这里</button>${humans>0?`<button data-add-bot="${i}">+ 强 AI</button>`:'<small>至少一名真人入座后才能加入 AI</small>'}`}</div>`).join('')}</div><div class="game-toolbar">${me>=0?`<button data-extra-ready class="${s.seats[me].ready?'':'primary'}">${s.seats[me].ready?'取消准备':'准备'}</button><button data-extra-leave>离座</button>${s.phase==='waiting'||s.phase==='result'?`<button data-extra-start ${canStart?'':'disabled'}>开始</button>`:''}`:''}</div>`}
function bindExtraSeats(e){e.querySelectorAll('[data-seat]').forEach(b=>b.onclick=()=>gameAction({type:'join',seat:+b.dataset.seat}));e.querySelectorAll('[data-add-bot]').forEach(b=>b.onclick=()=>gameAction({type:'add_bot',seat:+b.dataset.addBot}));e.querySelectorAll('[data-remove-bot]').forEach(b=>b.onclick=()=>gameAction({type:'remove_bot',seat:+b.dataset.removeBot}));e.querySelector('[data-extra-ready]')?.addEventListener('click',()=>gameAction({type:'ready'}));e.querySelector('[data-extra-leave]')?.addEventListener('click',()=>gameAction({type:'leave'}));e.querySelector('[data-extra-start]')?.addEventListener('click',()=>gameAction({type:'start'}))}
function relativeSeats(s,me){const base=me>=0?me:0;return {bottom:base,right:(base+1)%4,top:(base+2)%4,left:(base+3)%4}}
function playerBacks(n,type='card'){const lim=Math.min(Number(n)||0,type==='mj'?14:12);return `<div class="hand-backs ${type}">${Array.from({length:lim},()=>`<i class="${type==='mj'?'mj-back':'card-back'}"></i>`).join('')}${n>lim?`<b>×${n}</b>`:''}</div>`}
function fourSeatPanel(s,i,pos,type='card'){const p=s.seats?.[i],turn=s.turnSeat===i&&s.phase==='playing';return `<section class="four-seat ${pos} ${turn?'turn':''}"><div class="four-seat-head"><b>${i+1}号 · ${esc(seatName(p))}</b>${p?`<small>${p.isBot?'AI':p.ready?'READY':'未准备'}${p.handCount!=null?` · ${p.handCount}张`:''}</small>`:'<small>空位</small>'}</div>${p&&pos!=='bottom'?playerBacks(p.handCount??p.hand?.length??0,type):''}</section>`}
function unoCardFace(c,{button=false,index=null}={}){if(!c||c.hidden)return `<span class="uno-face back"><i>SL</i></span>`;const sym={skip:'⊘',reverse:'↻',draw2:'+2',wild:'★',wild4:'+4'},txt=sym[c.v]||c.v,color=c.c||'W',tag=button?'button':'span',attrs=button?` type="button" data-uno="${index}"`:'';return `<${tag}${attrs} class="uno-face c-${color}"><small>${esc(txt)}</small><b>${esc(txt)}</b><small>${esc(txt)}</small></${tag}>`}
function renderGo(e){
  const s=state.game,n=s.size||19,step=34,edge=18,size=edge*2+(n-1)*step,stars=n===19?[[3,3],[9,3],[15,3],[3,9],[9,9],[15,9],[3,15],[9,15],[15,15]]:[[2,2],[n-3,2],[Math.floor(n/2),Math.floor(n/2)],[2,n-3],[n-3,n-3]];
  e.innerHTML=`<div class="game-wrap go-game-wrap">${twoPlayerHeader(s,['黑棋','白棋'])}<div class="game-status">${s.winner?`${esc(userName(s.winner))} 获胜${s.result==='resign'?'（认输）':s.result==='time_forfeit'?'（超时）':''}`:s.started?`当前：${s.turn===0?'黑棋':'白棋'} · 黑提子 ${s.captures?.[0]||0} / 白提子 ${s.captures?.[1]||0}`:'等待双方准备'}${s.scores?` · 终局 ${s.scores[0].toFixed(1)} : ${s.scores[1].toFixed(1)}`:''}</div>${gameClockHtml(s)}<div class="board-shell go-board-shell"><div class="gomoku-board go-gomoku-board" style="width:${size}px;height:${size}px;--go-step:${step}px;--go-span:${(n-1)*step}px">${stars.map(([x,y])=>`<i class="board-star" style="left:${edge+x*step-3}px;top:${edge+y*step-3}px"></i>`).join('')}${s.board.flatMap((r,y)=>r.map((c,x)=>`<button class="gpoint ${s.last?.x===x&&s.last?.y===y?'last-move':''}" style="left:${edge+x*step-14}px;top:${edge+y*step-14}px" data-gx="${x}" data-gy="${y}" aria-label="${x+1},${y+1}">${c!=null?`<span class="stone ${c===0?'B':'W'}"></span>`:''}</button>`)).join('')}</div></div><div class="go-legend">19 路围棋 · 与五子棋完全相同的 34px 交叉点和棋子尺寸 · 黑先 · 白贴 6.5 目 · 提子 / 禁自杀 / 全局同形重复 / 连续停一手结算</div><div class="game-toolbar game-toolbar-docked"><button id="goPass" ${!s.started?'disabled':''}>停一手</button><button id="goResign" class="danger" ${!s.started?'disabled':''}>认输</button></div></div>`;
  bindBasic(e);e.querySelectorAll('[data-gx]').forEach(b=>b.onclick=()=>gameAction({type:'place',x:+b.dataset.gx,y:+b.dataset.gy}));$('#goPass').onclick=()=>gameAction({type:'pass'});$('#goResign').onclick=()=>confirm('确定认输本局？')&&gameAction({type:'resign'})
fitFixedBoard(e,'.go-gomoku-board',648,648);
}
function unoColorName(c){return ({R:'红',Y:'黄',G:'绿',B:'蓝'})[c]||c||'—'}
function unoColorPicker(idx){return `<div class="uno-color-picker"><b>万能牌：选择本轮颜色</b><div class="uno-color-options">${['R','Y','G','B'].map(c=>`<button type="button" data-uno-color="${c}" class="uno-color-choice c-${c}" aria-label="${unoColorName(c)}"><i></i><span>${unoColorName(c)}</span></button>`).join('')}<button type="button" data-uno-color-cancel>取消</button></div><small>选择后才会真正出牌，不再弹出输入窗口。</small></div>`}
function unoSortKey(c){const colors={R:0,Y:1,G:2,B:3,W:4},values={skip:20,reverse:21,draw2:22,wild:30,wild4:31};return [(colors[c?.c]??9),(/^\d$/.test(c?.v)?Number(c.v):(values[c?.v]??99)),String(c?.id||'')]}
