function socialPresenceSort(a,b){const rank=u=>!u.online?6:u.presenceStatus==='gaming'?0:u.presenceStatus==='listening'?1:u.presenceStatus==='voice'?2:u.presenceStatus==='online'?3:u.presenceStatus==='busy'?4:u.presenceStatus==='away'?5:6,ra=rank(a),rb=rank(b);if(ra!==rb)return ra-rb;if(ra>=5)return (b.lastSeenAt||0)-(a.lastSeenAt||0)||String(a.name||'').localeCompare(String(b.name||''),'zh-CN');return String(a.name||'').localeCompare(String(b.name||''),'zh-CN')}
function friendRows(arr,type){if(!arr.length)return'<p class="muted">暂无</p>';return [...arr].sort(socialPresenceSort).map(u=>{const unread=type==='friend'?Math.max(0,Number(u.unread??state.friendUnreadByUser?.[u.userId])||0):0;return `<div class="friend-row">${slime(u.slimeColor,'',u.userId)}<div class="grow"><b>${esc(u.name)}</b> ${u.online?'<span class="online-dot">● 在线</span>':'<span class="offline-dot">● 离线</span>'} ${statusBadge(u)}<br><small>${esc(u.loungeId)}${u.statusMessage?` · ${esc(u.statusMessage)}`:''}${u.activityLabel?` · ${esc(u.activityLabel)}`:u.currentRoomId?` · ${esc(u.currentRoomId)}`:''}</small></div>${type==='incoming'?`<button data-friend-action="accept" data-uid="${u.userId}">接受</button><button data-friend-action="reject" data-uid="${u.userId}" class="danger">拒绝</button>`:type==='friend'?`<button data-friend-chat="${u.userId}" class="primary friend-chat-btn">私聊${unread?`<span class="dm-unread-badge">${unread>99?'99+':unread}</span>`:''}</button><button class="danger" data-friend-action="remove" data-uid="${u.userId}">删除</button>`:'等待中'}</div>`}).join('')}
