function lastSeenText(ts){if(!ts)return'从未';const d=Math.max(0,Date.now()-ts);if(d<60000)return'刚刚';if(d<3600000)return`${Math.floor(d/60000)}分钟前`;if(d<86400000)return`${Math.floor(d/3600000)}小时前`;return new Date(ts).toLocaleDateString()}
function deviceMetaHtml(d){const ipKind=d.lastIpVersion===6?'IPv6':d.lastIpVersion===4?'IPv4':'IP',sys=[d.platform,d.platformVersion].filter(Boolean).join(' '),arch=[d.architecture,d.bitness?`${d.bitness}bit`:''].filter(Boolean).join(' '),hw=[d.screen?`屏幕 ${d.screen}`:'',d.hardwareConcurrency?`CPU ${d.hardwareConcurrency} 线程`:'',d.deviceMemory?`内存约 ${d.deviceMemory}GB`:'',d.maxTouchPoints?`触控 ${d.maxTouchPoints}`:''].filter(Boolean).join(' · ');return `<small>设备 ID：${esc(d.deviceId)}<br>客户端 IP（${ipKind}）：${esc(d.lastIp||'未知')} · 当前入口：${esc(d.lastHost||'未知')}<br>${sys||d.browser?`环境：${esc([sys,d.browser,arch].filter(Boolean).join(' · '))}<br>`:''}${hw?`${esc(hw)}<br>`:''}首次：${lastSeenText(d.createdAt)} · 最近：${lastSeenText(d.lastSeenAt)}${d.localOwnerDevice?' · 本机 Owner 设备':''}</small>${d.lastProxyIp||d.lastForwardedFor?`<details class="device-network-detail"><summary>代理 / IP 链路</summary><small>服务器看到的代理连接：${esc(d.lastProxyIp||'未知')}<br>X-Forwarded-For：${esc(d.lastForwardedFor||'无')}</small></details>`:''}`}
