function diagClock(ts){if(!ts)return'-';return new Date(Number(ts)||0).toLocaleString('zh-CN',{hour12:false})}
function diagUserPanel(d){
  const u=d.selectedUser,con=d.targetConnections||{};if(!u)return'';const meta=(d.diagUsers||[]).find(x=>x.userId===u.userId)||{},st=u.stats||{},ws=con.websocket||[],hp=con.httpFallback||[],dev=con.devices||[];
  const events=(u.events||[]).map(x=>`<div class="diag-log"><b>${esc(x.kind||'network')}</b>${x.status?` · HTTP ${Number(x.status)}`:''}<br><span>${esc(x.detail||'')}</span><div class="diag-log-meta"><span>${esc(diagClock(x.at))}</span><span>${esc(x.deviceLabel||x.deviceId||'未知设备')}</span><span>${esc(x.transport||'-')}</span><span>${esc(x.roomId||'-')}</span><span>${esc(x.clientIp||'-')}</span>${x.rttMs?`<span>RTT ${Number(x.rttMs)}ms</span>`:''}</div></div>`).join('')||'<div class="diag-empty">该用户最近没有网络事件。</div>';
  const reqs=(u.requests||[]).map(x=>`<div class="diag-log ${Number(x.status)>=500?'error':''}"><b>${esc(x.method)} ${esc(x.path)}</b> · HTTP ${Number(x.status)||0} · ${Number(x.ms)||0}ms<div class="diag-log-meta"><span>${esc(diagClock(x.at))}</span><span class="diag-log-user">${esc(x.deviceLabel||x.deviceId||'未知设备')}</span><span>${esc(x.transport||'-')}</span><span>${esc(x.roomId||'-')}</span><span>${esc(x.clientIp||'-')}</span></div></div>`).join('')||'<div class="diag-empty">该用户最近没有已记录请求。</div>';
  const deviceRows=dev.map(x=>`<div class="diag-row"><span>${esc(x.label||x.deviceId||'设备')}<br><small>${esc([x.platform,x.browser,x.model].filter(Boolean).join(' · ')||'环境未知')} · ${esc(x.lastIp||'IP未知')}</small></span><small>${esc(lastSeenText(x.lastSeenAt))}</small></div>`).join('')||'<div class="diag-empty">暂无设备信息。</div>';
  return `<div class="page-card"><div class="diag-user-head">${slime(meta.slimeColor||'mint','',meta.userId||u.userId)}<div class="grow"><h3>单用户网络日志 · ${esc(meta.name||meta.loungeId||u.userId)}</h3><small>${esc(meta.loungeId||u.userId)} · ${meta.online?'当前在线':'当前离线'} · ${esc(meta.presenceStatus||'')}</small></div></div><div class="diag-grid"><div><b>${Number(st.requests5m||0)}</b><small>5分钟请求</small></div><div><b>${Number(st.rateLimited5m||0)}</b><small>5分钟 429</small></div><div><b>${Number(st.errors5m||0)}</b><small>5分钟错误</small></div><div><b>${st.rttSamples?Number(st.avgRttMs):'-'}${st.rttSamples?' ms':''}</b><small>平均 RTT</small></div><div><b>${st.rttSamples?Number(st.p95RttMs):'-'}${st.rttSamples?' ms':''}</b><small>P95 RTT</small></div><div><b>${ws.length}</b><small>WebSocket</small></div><div><b>${hp.length}</b><small>HTTP兼容</small></div><div><b>${Number(con.activeTabs||0)}</b><small>活动页面</small></div></div><div class="diag-connection-list">${ws.map(x=>`<span class="diag-chip">WS · ${esc(x.roomId||'-')} · ${esc(x.deviceId||'-')}</span>`).join('')}${hp.map(x=>`<span class="diag-chip">HTTP · ${esc(x.roomId||'-')} · ${esc(x.tabId||'-')}</span>`).join('')||(!ws.length?'<span class="diag-chip">当前无房间实时连接</span>':'')}</div><details open><summary>设备 / 最近 IP</summary>${deviceRows}</details><details open><summary>客户端网络事件 (${(u.events||[]).length})</summary><div class="diag-section-scroll">${events}</div></details><details><summary>最近请求 (${(u.requests||[]).length})</summary><div class="diag-section-scroll">${reqs}</div></details></div>`;
}
